const readErr = $input.all().find(i => i.json && i.json.error);
if (readErr) throw new Error('Техкарти: ' + readErr.json.error);
const trig = $('Telegram Trigger').first();
const msg = trig.json.message || {};
const caption = String(msg.caption || '').trim();
const isActive = v => v === true || ['TRUE', '1', 'ТАК', 'YES'].includes(String(v ?? '').trim().toUpperCase());
const num = v => Number(String(v ?? '').replace(',', '.'));
const cards = $input.all().map(i => i.json)
  .filter(c => c && c.dish_id && c.dish_name && isActive(c.active))
  .map(c => ({ dish_id: String(c.dish_id).trim().toUpperCase(), dish_name: String(c.dish_name).trim(), aliases: String(c.aliases || ''), category: String(c.category || ''), norm_grams: num(c.norm_grams), tolerance_pct: num(c.tolerance_pct), visual_features: String(c.visual_features || '') }))
  .filter(c => Number.isFinite(c.norm_grams) && c.norm_grams > 0);
if (!cards.length) throw new Error('Техкарти: немає жодної активної позиції');
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-яіїєґ0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
const toks = s => norm(s).split(' ').filter(w => w.length >= 3 && !/\d/.test(w));
const names = c => [c.dish_name].concat(c.aliases.split(';')).map(norm).filter(Boolean);

let card = null, captionCandidates = [], normFromCaption = null, idGiven = false;
if (caption) {
  const capN = norm(caption);
  const idm = caption.match(/(?:^|[^a-zа-яіїєґ])[rр]\s?-?(\d{1,3})(?!\d)/i);
  if (idm) { idGiven = true; const id = 'R' + String(Number(idm[1])).padStart(2, '0'); card = cards.find(c => c.dish_id === id) || null; }
  if (!card) card = cards.find(c => names(c).includes(capN)) || null;
  if (!card) {
    const capW = toks(caption);
    if (capW.length) {
      const need = Math.max(1, Math.ceil(capW.length * 0.5));
      let bestS = 0, best = [];
      for (const c of cards) {
        const nt = names(c).flatMap(n => n.split(' ')).filter(w => w.length >= 3);
        let s = 0; for (const w of capW) if (nt.some(x => x === w || x.startsWith(w) || w.startsWith(x))) s++;
        if (s > bestS) { bestS = s; best = [c]; } else if (s === bestS && s > 0) best.push(c);
      }
      if (bestS >= need) { if (best.length === 1) card = best[0]; else captionCandidates = best.map(c => c.dish_id); }
    }
  }
  if (!card && !captionCandidates.length && !idGiven) {
    const gm = caption.match(/(\d{2,4})(?:[.,]\d+)?\s*(?:г|гр|g)?(?![\d])/i);
    if (gm) { const n = Number(gm[1]); if (n >= 20 && n <= 5000) normFromCaption = n; }
  }
}

const base = 'Подивись на фото страви на кухонних вагах. Зчитай показання дисплея — вагу в грамах. ВАЖЛИВО: дисплей може показувати число з десятковою крапкою або комою (напр. 384.8 або 384,8) — не пропускай її і поверни число саме як на дисплеї. Коротко опиши страву українською: тип (рол / макі / нігірі / гункан / сет / поке), що зверху, колір, чи є кунжут або соус, сира риба чи запечена / у клярі.';
const check = card ? ' Кухар підписав фото як «' + card.dish_name + '». Очікувані видимі ознаки за техкартою: ' + card.visual_features + '. Порівняй фото з цими ознаками: visual_match=false лише за явної невідповідності (інша риба чи топпінг, запечене замість сирого, інший тип страви); якщо ознаки не видно або є сумнів — visual_match=null.' : ' Підпису зі стравою немає, тому visual_match=null.';
const fmt = ' Поверни СТРОГО валідний JSON одним рядком без markdown: {"scale_grams": <число або null>, "readable": <true|false>, "looks_like": "<короткий опис>", "visual_match": <true|false|null>, "visual_reason": "<коротко чому, або порожньо>"}. Якщо цифри на дисплеї не видно — readable=false, scale_grams=null.';

return [{ json: { caption, card, match_source: card ? 'caption' : (normFromCaption ? 'norm' : ''), caption_candidates: captionCandidates, norm_from_caption: normFromCaption, cards, cards_count: cards.length, vision_prompt: base + check + fmt }, binary: trig.binary }];

const N = '\n';
const DEFAULT_TOL = 2.9;
const pre = $('Підпис → кандидат').first().json;
const msg = $('Telegram Trigger').first().json.message || {};
const cards = pre.cards || [];
const v = $input.first().json || {};
const vt = typeof v === 'string' ? v : (v.content ?? v.text ?? v.output ?? (v.message && v.message.content) ?? JSON.stringify(v));
let vp = {}; try { const m = String(vt).match(/\{[\s\S]*\}/); if (m) vp = JSON.parse(m[0]); } catch (e) {}
let scale = Number(String(vp.scale_grams ?? '').replace(',', '.'));
if (vp.scale_grams === null || vp.scale_grams === undefined || vp.scale_grams === '' || !Number.isFinite(scale) || scale <= 0) scale = null;
const readable = scale !== null && vp.readable !== false;
const looks = String(vp.looks_like || '').slice(0, 200);
const vmatch = vp.visual_match === true ? true : (vp.visual_match === false ? false : null);
const vreason = String(vp.visual_reason || '').slice(0, 200);
const visionEmpty = !('scale_grams' in vp) && !('readable' in vp);
const KINDS = [
  { re: /поке|боул|миск/, cats: ['поке'] },
  { re: /нігірі/, cats: ['нігірі'] },
  { re: /гункан|човник/, cats: ['гункани'] },
  { re: /рол|макі|сет/, cats: ['роли', 'запечені роли', 'темпура роли', 'макі', 'футомакі', 'сети'] }
];
const kindHit = KINDS.find(k => k.re.test(looks.toLowerCase()));
const kind = kindHit ? kindHit.cats : null;
const kindOk = c => !kind || kind.includes(c.category);
const tolOf = c => (Number.isFinite(c.tolerance_pct) && c.tolerance_pct > 0) ? c.tolerance_pct : DEFAULT_TOL;
const fixScale = (s, n) => (s != null && n && s >= n * 3 && s / 10 >= n * 0.5 && s / 10 <= n * 1.5) ? Math.round(s) / 10 : s;
const devOf = (s, n) => Math.round(((s - n) / n) * 1000) / 10;

let card = pre.card || null, source = pre.match_source || '', candidates = [];
let verdict, normG = null, tol = null, deviation = null, actual = scale;
if (!card && pre.caption_candidates && pre.caption_candidates.length) {
  const tied = cards.filter(c => pre.caption_candidates.includes(c.dish_id));
  if (scale != null) {
    const sc = tied.map(c => ({ c, d: Math.abs(devOf(fixScale(scale, c.norm_grams), c.norm_grams)) })).sort((a, b) => a.d - b.d);
    const ok = sc.filter(x => x.d <= tolOf(x.c));
    if (ok.length === 1) { card = ok[0].c; source = 'caption'; }
  }
  if (!card) candidates = tied.slice(0, 3);
}
if (!readable) verdict = 'UNREADABLE';
else if (card) {
  normG = card.norm_grams; tol = tolOf(card); actual = fixScale(scale, normG); deviation = devOf(actual, normG);
  verdict = (vmatch === false && pre.card) ? 'MISMATCH' : (Math.abs(deviation) <= tol ? 'OK' : 'BRAK');
} else if (pre.norm_from_caption) {
  normG = pre.norm_from_caption; tol = DEFAULT_TOL; actual = fixScale(scale, normG); deviation = devOf(actual, normG);
  verdict = Math.abs(deviation) <= tol ? 'OK' : 'BRAK'; source = 'norm';
} else if (candidates.length) {
  verdict = 'LOWCONF';
} else {
  const sc = cards.map(c => { const a = fixScale(scale, c.norm_grams); return { c, a, d: Math.abs(devOf(a, c.norm_grams)) }; }).sort((x, y) => x.d - y.d);
  const within = sc.filter(x => x.d <= tolOf(x.c) && kindOk(x.c));
  if (within.length === 1) { const x = within[0]; card = x.c; normG = card.norm_grams; tol = tolOf(card); actual = x.a; deviation = devOf(actual, normG); verdict = 'OK'; source = 'weight'; }
  else { verdict = 'LOWCONF'; const pool = within.length ? within : sc.filter(x => x.d <= 25); candidates = pool.slice().sort((a, b) => (kindOk(b.c) - kindOk(a.c)) || (a.d - b.d)).slice(0, 3).map(x => x.c); }
}

const now = new Date();
const ts = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv', dateStyle: 'short', timeStyle: 'medium' }).format(now);
const from = msg.from || {};
const chef = [from.first_name, from.last_name].filter(Boolean).join(' ') + (from.username ? ' (@' + from.username + ')' : '');
const sign = deviation != null && deviation > 0 ? '+' : '';
const title = card ? card.dish_id + ' · ' + card.dish_name : (pre.norm_from_caption ? 'Норма з підпису: ' + pre.norm_from_caption + ' г' : '');
const via = { caption: 'за підписом', norm: 'норма з підпису', weight: 'визначено за вагою — якщо страва інша, вкажіть назву або код у підписі' }[source] || '';
const weightLines = () => ['Норма: ' + normG + ' г ±' + tol + '%', 'На вагах: ' + actual + ' г', 'Відхилення: ' + sign + deviation + '%'];
const candLines = () => candidates.length ? ['Можливо:'].concat(candidates.map(c => '• ' + c.dish_id + ' ' + c.dish_name + ' — ' + c.norm_grams + ' г')) : [];
let lines;
if (verdict === 'OK') lines = ['✅ У нормі', title].concat(weightLines(), ['(' + via + ')']);
else if (verdict === 'BRAK') lines = ['⛔️ БРАК — поза допуском', title].concat(weightLines(), ['(' + via + ')', 'Записано в журнал.']);
else if (verdict === 'MISMATCH') lines = ['🚫 Фото не схоже на «' + card.dish_name + '»', 'Причина: ' + (vreason || looks || 'ознаки не збігаються з техкартою')].concat(weightLines(), ['Перевірте страву або підпис. Записано в журнал.']);
else if (verdict === 'LOWCONF') lines = ['⚠️ Не вдалося визначити позицію', (pre.caption && !pre.card && !pre.norm_from_caption && !(pre.caption_candidates || []).length) ? 'У техкарті не знайдено «' + pre.caption + '».' : '', 'На вагах: ' + (actual != null ? actual + ' г' : '—')].concat(candLines(), ['Вкажіть у підписі назву або код страви (напр. «R01»). Записано в журнал.']);
else lines = visionEmpty ? ['❓ Сервіс розпізнавання не відповів.', 'Надішліть фото ще раз. Записано в журнал.'] : ['❓ Не вдалося зчитати цифри на вагах.', 'Сфотографуйте так, щоб дисплей ваг було чітко видно. Записано в журнал.'];
const reply = lines.filter(Boolean).join(N);
const visual_check = (pre.card && source === 'caption') ? (vmatch === true ? 'match' : (vmatch === false ? 'mismatch' : 'unsure')) : 'n/a';

return [{ json: { ts, date: ts.slice(0, 10), chef, chat_id: String((msg.chat && msg.chat.id) ?? from.id ?? ''), dish_id: card ? card.dish_id : '', dish_name: card ? card.dish_name : (looks || pre.caption || ''), match_source: source, norm_grams: normG, actual_grams: actual, deviation_pct: deviation, tolerance_pct: tol, verdict, visual_check, visual_reason: visionEmpty ? 'vision: порожня відповідь' : (vreason || looks), tg_message_id: String(msg.message_id ?? ''), reply } }];

const N = '\n';
const readErr = $input.all().find(i => i.json && i.json.error);
if (readErr) throw new Error('Журнал: ' + readErr.json.error);
const msg = $('Telegram Trigger').first().json.message || {};
const rows = $input.all().map(i => i.json).filter(r => r && r.verdict);
const scopeAll = /(all|все|всі|усі|весь)/i.test(String(msg.text || ''));
const today = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv' }).format(new Date());
const inScope = scopeAll ? rows : rows.filter(r => String(r.date || '').slice(0, 10) === today);
const cnt = v => inScope.filter(r => r.verdict === v).length;
const devs = inScope.filter(r => r.verdict === 'OK' || r.verdict === 'BRAK').map(r => Math.abs(Number(String(r.deviation_pct).replace(',', '.')))).filter(Number.isFinite);
const avg = devs.length ? Math.round(devs.reduce((a, b) => a + b, 0) / devs.length * 10) / 10 : null;
const icon = { BRAK: '⛔️', MISMATCH: '🚫', LOWCONF: '⚠️', UNREADABLE: '❓' };
const failed = inScope.filter(r => r.verdict !== 'OK');
const lines = failed.slice(-20).reverse().map(r => (icon[r.verdict] || '•') + ' ' + String(r.ts || '').slice(5, 16) + ' ' + ([r.dish_id, r.dish_name].filter(Boolean).join(' ') || '—') + (r.actual_grams !== '' && r.actual_grams != null ? ': ' + r.actual_grams + ' г' : '') + (r.deviation_pct !== '' && r.deviation_pct != null ? ' (' + (Number(r.deviation_pct) > 0 ? '+' : '') + r.deviation_pct + '%)' : '') + (r.chef ? ' — ' + r.chef : ''));
let parts = ['📊 Статистика ' + (scopeAll ? 'за весь час' : 'за сьогодні (' + today + ')'), '', 'Всього перевірок: ' + inScope.length, '✅ У нормі: ' + cnt('OK'), '⛔️ Брак: ' + cnt('BRAK'), '🚫 Фото ≠ підпис: ' + cnt('MISMATCH'), '⚠️ Невизначено: ' + cnt('LOWCONF'), '❓ Нечитабельно: ' + cnt('UNREADABLE')];
if (avg != null) parts.push('Середнє відхилення: ' + avg + '%');
if (failed.length) { parts.push('', 'Останні проблемні (' + Math.min(20, failed.length) + ' з ' + failed.length + '):'); parts = parts.concat(lines); }
else parts.push('', 'Проблемних перевірок немає 👌');
if (!scopeAll) parts.push('', '«/stats all» — за весь час.');
return [{ json: { chat_id: String((msg.chat && msg.chat.id) ?? ''), reply: parts.join(N).slice(0, 3800) } }];
